var CHAT_EMOTE_TRAY_SIZE = 8;
var rows = emotes_default;
var catalog = new Map(rows.map((row) => [row.id, row]));
var known = new Set(catalog.keys());
function normalizeChatEmoteTrayIds(value) {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.filter((id) => typeof id === "string" && known.has(id)))].slice(0, CHAT_EMOTE_TRAY_SIZE);
}

// apps/mobile/src/core/equipment-crafting-prerequisites.ts
function quantity3(state, itemId) {
  return (state.inventory.stacks.find((row) => row.itemId === itemId)?.quantity ?? 0) + (state.bank.stacks.find((row) => row.itemId === itemId)?.quantity ?? 0);
}
function processingRecipeFor(itemId) {
  return RECIPES.filter((recipe2) => {
    if (recipe2.output.itemId !== itemId || recipe2.skillId !== "smithing" || recipe2.noviceSetId || timedEquipmentRecipe(recipe2.id)) return false;
    return itemDef(recipe2.output.itemId).type === "material";
  }).sort((a, b) => a.level - b.level || a.gold - b.gold || a.seconds - b.seconds)[0];
}
function craftEquipmentPrerequisites(state, equipmentRecipeId, nowMs) {
  const equipment = timedEquipmentRecipe(equipmentRecipeId);
  if (!equipment) throw new Error("This equipment recipe does not use the forge");
  if (!state.character) throw new Error("Create a character first");
  if (equipment.classId && equipment.classId !== state.character.classId) throw new Error("This equipment recipe belongs to another class");
  let next = structuredClone(state), stepClock = 0;
  const craftedByRecipe = /* @__PURE__ */ new Map();
  const visiting = /* @__PURE__ */ new Set();
  const ensure = (itemId, target2) => {
    if (quantity3(next, itemId) >= target2) return;
    const recipe2 = processingRecipeFor(itemId);
    if (!recipe2) throw new Error(`Need ${target2 - quantity3(next, itemId)} more ${itemDef(itemId).name} from gathering, combat or another external source`);
    if (visiting.has(itemId)) throw new Error("Crafting prerequisite cycle detected");
    visiting.add(itemId);
    while (quantity3(next, itemId) < target2) {
      for (const input of recipe2.inputs) ensure(input.itemId, input.quantity);
      try {
        next = craftRecipe(next, recipe2.id, nowMs + ++stepClock);
      } catch (error) {
        throw new Error(`Cannot craft prerequisite ${recipe2.name}: ${error instanceof Error ? error.message : "requirements missing"}`);
      }
      const existing = craftedByRecipe.get(recipe2.id);
      if (existing) {
        existing.batches++;
        existing.quantity += recipe2.output.quantity;
      } else craftedByRecipe.set(recipe2.id, { recipeId: recipe2.id, name: recipe2.name, batches: 1, outputItemId: recipe2.output.itemId, quantity: recipe2.output.quantity });
    }
    visiting.delete(itemId);
  };
  for (const input of equipment.inputs) ensure(input.itemId, input.quantity);
  if (!craftedByRecipe.size) throw new Error("No processable prerequisites are currently missing");
  return { state: next, equipmentRecipeId, crafted: [...craftedByRecipe.values()] };
}

// apps/mobile/src/dev/debug-tools.ts
init_progression();
function requireCharacter(state) {
  if (!state.character) throw new Error("Debug action requires a character");
  return state.character;
}
function debugSetLevel(state, level) {
  const c = requireCharacter(state);
  const clamped = Math.max(1, Math.min(100, Math.floor(level)));
  const xp = characterTotalXpAtLevel(clamped);
  const unlocked = MONSTERS.filter((m) => m.unlockLevel <= clamped).map((m) => m.id);
  return { ...state, character: { ...c, level: clamped, xp }, unlockedMonsterIds: [.../* @__PURE__ */ new Set([...state.unlockedMonsterIds, ...unlocked])] };
}
function debugAddItem(state, itemId, quantity4 = 1) {
  itemDef(itemId);
  const incoming = { itemId, quantity: Math.max(1, Math.floor(quantity4)) };
  return { ...state, inventory: { ...state.inventory, stacks: stackItems(state.inventory.stacks, [incoming]) } };
}
function debugAddQaSupplies(state, quantity4 = 9999) {
  let next = state;
  for (const item of ITEMS) {
    if (item.type === "gear") continue;
    next = debugAddItem(next, item.id, quantity4);
  }
  return next;
}
function debugPrepareEquipmentLab(state) {
  const c = requireCharacter(state), skillXp = totalXpAtLevel(100);
  let next = {
    ...state,
    character: { ...c, gold: 5e7 },
    inventory: { ...state.inventory, capacity: Math.max(state.inventory.capacity, 5e3) },
    bank: { ...state.bank, capacity: Math.max(state.bank.capacity, 5e3) },
    skills: state.skills.map((skill2) => ({ ...skill2, xp: skillXp, level: 100 })),
    account: {
      ...state.account,
      createdCharacterCount: Math.max(state.account.createdCharacterCount, 4),
      unlockedCharacterSlots: 5,
      entitlements: { ...state.account.entitlements ?? {}, supporter: true, vip_plus: true }
    }
  };
  next = debugAddQaSupplies(next);
  return next;
}
function debugPrepareDungeonLab(state) {
  let next = debugSetLevel(state, 100);
  const c = requireCharacter(next), set = noviceSetFor(c.classId), equipment = { ...c.equipment };
  for (const slot of set.slots) equipment[slot] = noviceItemId(c.classId, slot);
  const crafted = [.../* @__PURE__ */ new Set([...c.craftedNoviceItemIds ?? [], ...set.slots.map((slot) => noviceItemId(c.classId, slot))])];
  next = {
    ...next,
    character: { ...c, equipment, craftedNoviceItemIds: crafted, currentHp: Math.max(c.currentHp, c.hp) },
    unlockedMonsterIds: MONSTERS.map((monster) => monster.id)
  };
  return next;
}
function debugPrepareFullQaSandbox(state) {
  let next = debugPrepareEquipmentLab(debugPrepareDungeonLab(state));
  next = {
    ...next,
    quests: next.quests.map((quest) => ({ ...quest, status: "claimed", progress: Number.MAX_SAFE_INTEGER })),
    unlockedMonsterIds: MONSTERS.map((monster) => monster.id),
    defeatedBossIds: [.../* @__PURE__ */ new Set([...next.defeatedBossIds, ...MONSTERS.filter((monster) => monster.boss).map((monster) => monster.id)])],
    account: {
      ...next.account,
      guildMember: true,
      guildContribution: Math.max(next.account.guildContribution ?? 0, 25e3),
      premiumCurrencyBalance: Math.max(next.account.premiumCurrencyBalance ?? 0, 99999)
    }
  };
  return next;
}

// apps/mobile/src/dev/admin-qa-profile.ts
function freshQaCharacter(classId, bodyPresentation, nowMs) {
  return createCharacter(newGame(nowMs), classId, "Veldryn Admin", bodyPresentation);
}
function buildAdminQaState(current, classId = "IRONWARDEN", nowMs = Date.now()) {
  const bodyPresentation = current?.character?.bodyPresentation ?? "male";
  const base = current?.character?.classId === classId && (current.character.profileTitle === "QA Administrator" || current.character.name === "Veldryn Admin") ? current : freshQaCharacter(classId, bodyPresentation, nowMs);
  const prepared = debugPrepareFullQaSandbox(base);
  if (!prepared.character) return prepared;
  return { ...prepared, character: { ...prepared.character, classSkills: classSkillsFor(classId).map((skill2) => ({ skillId: skill2.id, xp: MAX_CLASS_SKILL_XP, level: 100 })) } };
}
function refillAdminQaResources(state) {
  return debugPrepareFullQaSandbox(state);
}

